mapper.select:
SELECT JOB.ID AS JOB_ID, JOB.REPOSITORY_ID, JOB.COMMIT_HASH, JOB.BRANCH_NAME, JOB.TRIGGERED_BY, JOB.CREATED_AT AS JOB_CREATED_AT, REPOSITORY.OWNER_TYPE AS REPOSITORY_OWNER_TYPE, REPOSITORY.OWNER_ID AS REPOSITORY_OWNER_ID, REPOSITORY.CLONE_PATH AS REPOSITORY_CLONE_PATH FROM JOB JOB JOIN REPOSITORY REPOSITORY ON REPOSITORY.ID = JOB.REPOSITORY_ID WHERE EXISTS ( SELECT 1 FROM JOB_HISTORY JOB_HISTORY WHERE JOB_HISTORY.JOB_ID = JOB.ID AND JOB_HISTORY.STATUS = 'PENDING' AND NOT EXISTS ( SELECT 1 FROM JOB_HISTORY NEWER WHERE NEWER.JOB_ID = JOB_HISTORY.JOB_ID AND ( NEWER.CREATED_AT > JOB_HISTORY.CREATED_AT OR (NEWER.CREATED_AT = JOB_HISTORY.CREATED_AT AND NEWER.ID > JOB_HISTORY.ID) ) ) )
AND REPOSITORY.OWNER_TYPE = 'ORGANIZATION' AND REPOSITORY.OWNER_ID = #{scopeTargetId}
AND REPOSITORY.ID = #{scopeTargetId}
ORDER BY JOB.CREATED_AT ASC, JOB.ID ASC limit 1
